[Form]
public class UPSPricingAttributeGroup extends FormRun
{
    UPSPricingAttributeTmp priceAttributes;

    UPSPricingAttributeGroupType groupType;

    Query productPreviewQuery;
    Query custPreviewQuery;

}

private void initPriceAttributeTmp()
{
    // TODO
    select firstonly RecId from priceAttributes;
    if (!priceAttributes.RecId)
    {
        List attributes = UPSPricingAttributeRepository::getAllPricingAttributes();
        Enumerator enum = attributes.getEnumerator();

        ttsbegin;

        UPSIPricingAttribute pricingAttr;
        UPSPricingAttributeLink link;
        int cnt = 1;
        DictClass dc;

        while (enum.moveNext())
        {
            pricingAttr = enum.current();
            link = UPSPricingAttributeRepository::toPriceAttributeLink(pricingAttr);
            priceAttributes.AttributeName = link.AttributeName;
            priceAttributes.PriceAttributeClassId = link.PriceAttributeClassId;
            priceAttributes.TypeName = link.TypeName;
            priceAttributes.ProviderClassId = link.AttributeProviderClassId;
            priceAttributes.Id = cnt;
            dc = link.PriceAttributeClassId == classNum(UPSPricingAttributeEcoResAttribute) ? new DictClass(link.AttributeProviderClassId) : new DictClass(link.PriceAttributeClassId);
            priceAttributes.Level = (dc.getAttribute('UPSPricingAttributeSourceDiscoveryAttribute') as UPSPricingAttributeSourceDiscoveryAttribute).parmLevel();
            priceAttributes.Source = link.getPriceAttributeSourceSymbol();
            priceAttributes.PriceAttributeClassName = classId2Name(link.PriceAttributeClassId);
            priceAttributes.insert();
            cnt++;
        }
        ttscommit;
    }
}

public void init()
{
    switch (element.args().menuItemName())
    {
        case menuItemDisplayStr(UPSPricingAttributeGroupCust):
            groupType = UPSPricingAttributeGroupType::Customer;               
            break;

        case menuItemDisplayStr(UPSPricingAttributeGroupProduct):
            groupType = UPSPricingAttributeGroupType::Product;
            break;
        default:
            groupType = UPSPricingAttributeGroupType::General;
    }

    super();

    UPSPricingAttributeRepository::clearCache();
    element.initPriceAttributeTmp();
    element.setControlsVisible();
}

/// <summary>
/// Set controls visibility
/// </summary>
private void setControlsVisible()
{
    switch (groupType)
    {
        case UPSPricingAttributeGroupType::Customer:
            PreviewCustTabPage.visible(true);
            PreviewProductTabPage.visible(false);

            UPSPricingAttributeGroup_ds.object(fieldNum(UPSPricingAttributeGroup, SourceLevel)).enabled(false);
            break;

        case UPSPricingAttributeGroupType::Product:
            PreviewCustTabPage.visible(false);
            PreviewProductTabPage.visible(true);

            UPSPricingAttributeGroup_ds.object(fieldNum(UPSPricingAttributeGroup, SourceLevel)).enabled(false);
            break;

        default:
            PriceAttribute_Value.visible(false);
            PreviewCustTabPage.visible(false);
            PreviewProductTabPage.visible(false);
    }
}

/// <summary>
/// Expand product variants
/// </summary>
/// <param name = "_qbdsParent">Parent data source</param>
/// <param name = "_joinMode">Join mode</param>
public void addAllProductVariants(QueryBuildDataSource _qbdsParent, JoinMode _joinMode = JoinMode::InnerJoin)
{
    QueryBuildDataSource qbdsInventDimCombination = _qbdsParent.addDataSource(tableNum(InventDimCombination));

    qbdsInventDimCombination.addLink(fieldNum(InventTable, ItemId), fieldNum(InventDimCombination, ItemId));
    qbdsInventDimCombination.joinMode(_joinMode);
}

/// <summary>
/// Link line type table to Customer/Item/Product variant data source
/// </summary>
/// <param name = "_qbdsParent">Parent Customer/Item/Product data source</param>
private void addLineTypeLink(QueryBuildDataSource _qbdsParent)
{
    QueryBuildDataSource qbdsLineState = _qbdsParent.addDataSource(tableNum(UPSPricingAttributeLineState));
    qbdsLineState.relations(true);
    qbdsLineState.joinMode(JoinMode::OuterJoin);

    qbdsLineState.addRange(fieldNum(UPSPricingAttributeLineState, PricingAttributeGroup)).value(queryValue(UPSPricingAttributeGroup.RecId));
}

/// <summary>
/// Filter preview query according to slected pricing attributes
/// </summary>
private void researchPreviewQuery()
{
    switch (groupType)
    {
        case UPSPricingAttributeGroupType::Customer:
            custPreviewQuery = UPSPricingObjectQueryBuilder::constructFromPricingGroup(UPSPricingAttributeGroup).build();
            element.addLineTypeLink(custPreviewQuery.dataSourceTable(tableNum(CustTable)));

            CustTable_ds.executeQuery();
            break;

        case UPSPricingAttributeGroupType::Product:
            productPreviewQuery = UPSPricingObjectQueryBuilder::constructFromPricingGroup(UPSPricingAttributeGroup).build();

            if (UPSPricingAttributeGroup.ProductAllVariants == NoYes::Yes)
            {
                element.addAllProductVariants(productPreviewQuery.dataSourceTable(tableNum(InventTable)));
                element.addLineTypeLink(productPreviewQuery.dataSourceTable(tableNum(InventDimCombination)));
            }
            else
            {
                element.addAllProductVariants(productPreviewQuery.dataSourceTable(tableNum(InventTable)), JoinMode::OuterJoin);
                element.addLineTypeLink(productPreviewQuery.dataSourceTable(tableNum(InventTable)));                    
            }

            InventTable_ds.executeQuery();                
            break;
    }
}

public void updateControlsForPricingAttributeLink(boolean _enabled)
{
    NewLine.enabled(_enabled);
    DeleteLine.enabled(_enabled);
    UpButton.enabled(_enabled);
    DownButton.enabled(_enabled);
}

/// <summary>
/// Initialize default fields values
/// </summary>
public void initValue()
{
    super();

    UPSPricingAttributeGroup.GroupType = groupType;

    switch (groupType)
    {
        case UPSPricingAttributeGroupType::Customer:
            UPSPricingAttributeGroup.SourceLevel = UPSPricingAttributeSourceLevel::Header;
            break;

        case UPSPricingAttributeGroupType::Product:
            UPSPricingAttributeGroup.SourceLevel = UPSPricingAttributeSourceLevel::Line;
            break;
    }

}

/// <summary>
/// Init data source ranges
/// </summary>
public void init()
{
    QueryBuildRange qbrGroupType;

    super();

    qbrGroupType = SysQuery::findOrCreateRange(UPSPricingAttributeGroup_ds.queryBuildDataSource(), fieldNum(UPSPricingAttributeGroup, GroupType));
    qbrGroupType.value(queryValue(groupType));
}

/// <summary>
/// Record active
/// </summary>
/// <returns>Int</returns>
public int active()
{
    int ret;

    ret = super(); 

    AllVariantsBtn.enabled(UPSPricingAttributeGroup.ProductAllVariants == NoYes::Yes ? false : true);
    InventDimCombination_DistinctProductVariant.visible(UPSPricingAttributeGroup.ProductAllVariants == NoYes::Yes ? true : false);

    if (UPSPricingAttributeGroup)
    {
        element.researchPreviewQuery();
        element.updateControlsForPricingAttributeLink(true);
    }

    return ret;
}

public void resetValidation()
{
    if (UPSPricingAttributeGroup.IsValid)
    {
        ttsbegin;
        UPSPricingAttributeGroup.IsValid = NoYes::No;
        ttscommit;
        info("@UnifiedPricingService:UPSPricingAttributeGroup_ResetValidation");
    }
}

public edit Name editAttributeName(boolean _set, UPSPricingAttributeLink _link, Name _name)
{
    if (_set)
    {
        var rec = str2Int(_name);
        select firstonly * from priceAttributes where priceAttributes.Id == rec;

        UPSIPricingAttribute priceAttribute = UPSPricingAttributeRepository::priceAttribute(
            priceAttributes.PriceAttributeClassId, priceAttributes.ProviderClassId, priceAttributes.AttributeName, priceAttributes.TypeName);

        _link.PriceAttributeClassId = classIdGet(priceAttribute);
        _link.AttributeName = priceAttributes.AttributeName;
        _link.AttributeProviderClassId = priceAttributes.ProviderClassId;
        _link.TypeName = priceAttributes.TypeName;
        _link.DisplayOrder = this.getLargestDisplayOrder();
    }

    return _link.AttributeName;
}

public edit Name editAttributeDefaultValue(boolean _set, UPSPricingAttributeLink _link, Name _name)
{

    // When change value.
    if (_set)
    {
        _link.DefaultValue = _name;
    }

    return UPSPricingAttributeAllowedValueLookup::getPriceAttributeValue(_link.AttributeName, _link.DefaultValue);
}

public display str displayAttributeType(UPSPricingAttributeLink _link)
{
    str typeName;

    if (_link.AttributeName)
    {
        typeName = enum2Symbol(enumNum(AttributeDataType), _link.pricingAttribute().getDataType());
    }

    return typeName;
}

public display str displayAttributeSource(UPSPricingAttributeLink _link)
{
    str source;

    if (_link.AttributeName)
    {
        DictClass dc;
        dc = _link.PriceAttributeClassId == classNum(UPSPricingAttributeEcoResAttribute) ? new DictClass(_link.AttributeProviderClassId) : new DictClass(_link.PriceAttributeClassId);
        source = enum2Symbol(enumNum(UPSPricingAttributeSource), (dc.getAttribute('UPSPricingAttributeSourceDiscoveryAttribute') as UPSPricingAttributeSourceDiscoveryAttribute).parmSource());
    }

    return source;
}

public void write()
{
    boolean priceAttributeChanged = (UPSPricingAttributeLink.orig().AttributeName != UPSPricingAttributeLink.AttributeName ||
        UPSPricingAttributeLink.orig().TypeName != UPSPricingAttributeLink.TypeName ||
        UPSPricingAttributeLink.orig().PriceAttributeClassId != UPSPricingAttributeLink.PriceAttributeClassId);

    super();

    if (priceAttributeChanged)
    {
        UPSPricingAttributeGroup_ds.resetValidation();
    }

    element.researchPreviewQuery();
}

public int getLargestDisplayOrder()
{
    UPSPricingAttributeLink link;
    select firstonly DisplayOrder from link order by DisplayOrder desc
        where link.PriceAttributeGroup == UPSPricingAttributeLink.PriceAttributeGroup;
    return link.DisplayOrder + 1;
}

public void create(boolean _append = false)
{
    this.last();
    super(true);
}

public void delete()
{
    super();

    UPSPricingAttributeGroup_ds.resetValidation();
}

public void init()
{
    super();
    this.query().dataSourceTable(tableNum(UPSPricingAttributeLink)).addSortField(fieldNum(UPSPricingAttributeLink, DisplayOrder));
}

public int active()
{
    int ret = super();

    element.updateControlsForPricingAttributeLink(
        !UPSPricingAttributeLink.RecId || !UPSPricingAttributeGroup::isPricingAttributeGroupUsed(UPSPricingAttributeLink.PriceAttributeGroup));

    return ret;
}

/// <summary>
/// Execute query for customer data source
/// </summary>
public void executeQuery()
{
    if (custPreviewQuery)
    {
        this.query(custPreviewQuery);
    }

    super();
}

/// <summary>
/// Execute query for product data source
/// </summary>
public void executeQuery()
{
    if (productPreviewQuery)
    {
        this.query(productPreviewQuery);
    }

    InventDimCombination_ds.queryBuildDataSource().enabled(UPSPricingAttributeGroup.ProductAllVariants == NoYes::Yes ? true : false);

    super();
}

public void clicked()
{
    super();

    ttsbegin;
    UPSPricingAttributeGroup.IsValid = UPSPricingAttributeGroup.validateStructure() ? NoYes::Yes : NoYes::No;
    UPSPricingAttributeGroup.update();
    ttscommit;
}

public void clicked()
{
    super();
    element.initPriceAttributeTmp();
    xArgs args = new Args();

    Form _form = new Form(formStr(TestUPSRemoveDuplicateClassForm));
    args.object(_form);
    args.record(element.priceAttributes);

    FormRun attributeGroupTreeFromRun = ClassFactory.formRunClass(args);

    attributeGroupTreeFromRun.init();
    attributeGroupTreeFromRun.run();
    attributeGroupTreeFromRun.wait();
}

void clicked()
{
    UPSPricingAttributeLink pricingAttributeLink;

    super();

    pricingAttributeLink = UPSPricingAttributeLink::find(UPSPricingAttributeLink.RecId, true);

    pricingAttributeLink.moveUp();
    UPSPricingAttributeLink_ds.research(false);
    UPSPricingAttributeLink_ds.positionToRecord(pricingAttributeLink);
}

void clicked()
{
    UPSPricingAttributeLink pricingAttributeLink;

    super();

    pricingAttributeLink = UPSPricingAttributeLink::find(UPSPricingAttributeLink.RecId, true);

    pricingAttributeLink.moveDown();
    UPSPricingAttributeLink_ds.research(false);
    UPSPricingAttributeLink_ds.positionToRecord(pricingAttributeLink);
}

public void lookup()
{
    Query                   query          = new Query();
    QueryBuildDataSource    queryBuildDataSource;
    QueryBuildRange         queryBuildRange;
    QueryBuildRange         queryBuildRangeSource;
    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tablenum(UPSPricingAttributeTmp), this);

    element.initPriceAttributeTmp();
    queryBuildDataSource = query.addDataSource(tablenum(UPSPricingAttributeTmp));

    queryBuildRange = queryBuildDataSource.addRange(fieldNum(UPSPricingAttributeTmp, Level));
    queryBuildRange.value(UPSPricingAttributeGroup_SourceLevel.valueStr());

    if (groupType == UPSPricingAttributeGroupType::Customer)
    {
        queryBuildRangeSource = queryBuildDataSource.addRange(fieldNum(UPSPricingAttributeTmp, Source));
        queryBuildRangeSource.value(enum2Symbol(enumNum(UPSPricingAttributeSource), UPSPricingAttributeSource::Customer) + ',' + enum2Symbol(enumNum(UPSPricingAttributeSource), UPSPricingAttributeSource::SalesTable));
    }
    else if (groupType == UPSPricingAttributeGroupType::Product)
    {
        queryBuildRangeSource = queryBuildDataSource.addRange(fieldNum(UPSPricingAttributeTmp, Source));
        queryBuildRangeSource.value(enum2Symbol(enumNum(UPSPricingAttributeSource), UPSPricingAttributeSource::Product) + ',' + enum2Symbol(enumNum(UPSPricingAttributeSource), UPSPricingAttributeSource::SalesLine));
    }

    queryBuildDataSource.addSortField(fieldNum(UPSPricingAttributeTmp, Source));
    queryBuildDataSource.addSortField(fieldNum(UPSPricingAttributeTmp, AttributeName));
    sysTableLookup.addLookupfield(fieldnum(UPSPricingAttributeTmp, Id));
    sysTableLookup.addLookupfield(fieldnum(UPSPricingAttributeTmp, AttributeName));
    sysTableLookup.addLookupMethod(tableMethodStr(UPSPricingAttributeTmp, displayDataType));
    sysTableLookup.addLookupfield(fieldnum(UPSPricingAttributeTmp, TypeName));
    sysTableLookup.addLookupfield(fieldnum(UPSPricingAttributeTmp, Source));
    sysTableLookup.parmQuery(query);
    sysTableLookup.parmTmpBuffer(priceAttributes);
    sysTableLookup.performFormLookup();

    // TODO return set class id back to link.
}

// Clear default value only when selected attribute changed.
public void textChange()
{
    super();
    UPSPricingAttributeLink.DefaultValue = '';
}

public void lookup()
{
    UPSPricingAttributeAllowedValueLookup::doLookUp(this, UPSPricingAttributeLink);

    super();
}

public void enter()
{
    // Prohibit customized input for 'fixed value' or 'referenced' price attribute.
    UPSIPricingAttribute priceAttribute = UPSPricingAttributeLink.pricingAttribute();
    //info(strFmt("enum id %1", priceAttribute.getFixedAllowedValueEnumId()));
    if (priceAttribute.getFixedAllowedValueEnumId() != UPSAbstractPricingAttribute::ENUM_ID_NOT_EXIST
        || priceAttribute.getDataType() == AttributeDataType::Reference)
    {
        PriceAttribute_Value.lookupOnly(true);
    }
    else
    {
        PriceAttribute_Value.lookupOnly(false);
    }

    super();
}

/// <summary>
/// Exclude record from pricing query
/// </summary>
public void clicked()
{
    CustTable custTableLocal;

    super();

    for(custTableLocal = CustTable_ds.getFirst(true) ? CustTable_ds.getFirst(true) : CustTable_ds.cursor(); 
        custTableLocal; 
        custTableLocal = CustTable_ds.getNext())
    {
        UPSPricingAttributeLineState::excludeLine(UPSPricingAttributeGroup.RecId, custTableLocal.TableId, custTableLocal.RecId);
    }

    CustTable_ds.research(true);
    CustTable_ds.refresh();
}

/// <summary>
/// Exclude record from pricing query
/// </summary>
public void clicked()
{            
    super();

    if (UPSPricingAttributeGroup.ProductAllVariants == NoYes::Yes)
    {
        InventDimCombination inventDimCombinationLocal;

        for (   inventDimCombinationLocal = InventDimCombination_ds.getFirst(true) ? InventDimCombination_ds.getFirst(true) : InventDimCombination_ds.cursor();
                inventDimCombinationLocal;
                inventDimCombinationLocal = InventDimCombination_ds.getNext())
        {
            UPSPricingAttributeLineState::excludeLine(UPSPricingAttributeGroup.RecId, inventDimCombinationLocal.TableId, inventDimCombinationLocal.RecId);
        }
    }
    else
    {
        InventTable inventTableLocal;

        for (   inventTableLocal = InventTable_ds.getFirst(true) ? InventTable_ds.getFirst(true) : InventTable_ds.cursor();
                inventTableLocal;
                inventTableLocal = InventTable_ds.getNext())
        {
            UPSPricingAttributeLineState::excludeLine(UPSPricingAttributeGroup.RecId, inventTableLocal.TableId, inventTableLocal.RecId);
        }
    }

    InventTable_ds.research(true);
    InventTable_ds.refresh();
}

/// <summary>
/// Expand product variants
/// </summary>
public void clicked()
{
    super();

    if (UPSPricingAttributeGroup.ProductAllVariants == NoYes::No)
    {
        UPSPricingAttributeGroup.ProductAllVariants = NoYes::Yes;
        UPSPricingAttributeGroup.write();

        AllVariantsBtn.enabled(false);
        InventDimCombination_DistinctProductVariant.visible(true);
    }

    element.researchPreviewQuery();
}
